/*  Exception and interrupt vector table for the Cortex-M85 example.
 *
 *  Armv8-M names its exception handlers the CMSIS way, so this table cannot be
 *  the Armv7-M one with the core name changed: the port and its low level
 *  initialisation export SVC_Handler, PendSV_Handler, SysTick_Handler and
 *  HardFault_Handler, where the Cortex-M3, M4 and M7 examples reference
 *  __tx_SVCallHandler, __tx_PendSVHandler, __tx_SysTickHandler and
 *  __tx_HardfaultHandler. Linking the Armv7-M table here fails to resolve every
 *  one of those.
 *
 *  Slot 7 is SecureFault on Armv8-M, where Armv7-M leaves it reserved.
 */

  .global reset_handler
  .global __tx_NMIHandler
  .global __tx_BadHandler
  .global SVC_Handler
  .global PendSV_Handler
  .global SysTick_Handler
  .global HardFault_Handler
  .global UsageFault_Handler
  .global __tx_DBGHandler

  .syntax unified
  .section .vectors, "ax"
  .code 16
  .align 0
  .global _vectors

_vectors:
  .word __stack_end__
  .word reset_handler
  .word __tx_NMIHandler
  .word HardFault_Handler
  .word __tx_BadHandler       // MemManage
  .word __tx_BadHandler       // BusFault
  .word UsageFault_Handler
  .word __tx_BadHandler       // SecureFault, Armv8-M only
  .word 0 // Reserved
  .word 0 // Reserved
  .word 0 // Reserved
  .word SVC_Handler           // Used by the ThreadX scheduler
  .word __tx_DBGHandler
  .word 0 // Reserved
  .word PendSV_Handler        // Used by the ThreadX scheduler
  .word SysTick_Handler       // Used by the ThreadX timer
  .word __tx_BadHandler       // Populate with a user interrupt handler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler
  .word __tx_BadHandler

  .section .init, "ax"
  .thumb_func
reset_handler:
  // low level hardware config, such as PLL setup goes here
  b _start
